"""Build Scratch SD bridge slides using the project's established bridge design system."""
from pathlib import Path
import html, json

ROOT = Path(__file__).resolve().parents[1]
SLIDES = ROOT / "slides"
DRAFT = ROOT / "drafts" / "sd-scratch"
REFERENCE = SLIDES / "bridge-ms-00.html"
SLIDES.mkdir(exist_ok=True); DRAFT.mkdir(parents=True, exist_ok=True)

raw = REFERENCE.read_text(encoding="utf-8")
css = raw.split("<style>", 1)[1].split("</style>", 1)[0]
css += """
.source{font-size:14px;color:#333;margin-top:18px}.source a{color:#0056b3}.image-note{font-size:15px;font-weight:600;margin-top:8px;color:#333}.screenshot-box img{max-height:330px}.feature-card p,.feature-card li{font-size:18px;line-height:1.5}.mini-card{background:#fff;border:3px solid var(--black);border-radius:14px;padding:16px;box-shadow:4px 4px 0 var(--black);margin-bottom:12px}.mini-card h3{margin:0 0 8px}.two-column{align-items:stretch}.slide-text img{max-width:100%}
"""

IMG = "../assets/scratch/"
def image(file, alt, caption):
    return f'''<div class="screenshot-box"><img src="{IMG}{file}" alt="{html.escape(alt)}" class="screenshot-img"><div class="screenshot-caption">🖼️ {html.escape(caption)}</div></div>'''
def card(title, body, style=""):
    return f'<div class="mini-card" style="{style}"><h3>{title}</h3><p>{body}</p></div>'
def slide(title, subtitle, body):
    return f'''<div class="slide" data-title="{html.escape(title)}" data-subtitle="{html.escape(subtitle)}"><div class="content-card"><div class="inner-content"><h2 class="slide-title">{title}</h2><div class="slide-text">{body}</div></div></div></div>'''
def quiz(question, options, answer):
    opts = "".join(f'<button class="quiz-option" onclick="this.parentElement.querySelectorAll(\'.quiz-option\').forEach(x=>x.classList.remove(\'correct\',\'wrong\'));this.classList.add(\'{"correct" if i==answer else "wrong"}\')">{chr(65+i)}. {x}</button>' for i,x in enumerate(options))
    return f'<div class="feature-card quiz"><h3>🧠 Cek pemahaman</h3><p>{question}</p>{opts}</div>'

def nav(n):
    return f'''<div class="nav-container"><button id="btnPrev" class="nav-btn" disabled>← Prev</button><div class="counter-group"><div class="slide-counter">Slide <span id="counter">1</span> dari <span id="totalSlides">{n}</span></div><div class="progress-bar-bg"><div id="bar" class="progress-bar" style="width:6.25%"></div></div></div><button id="btnNext" class="nav-btn">Next →</button></div>'''

def html_doc(meta, sections):
    slides = ''.join(slide(*x) for x in sections)
    return f'''<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>{html.escape(meta['title'])}</title><style>{css}</style></head><body><div class="app-container"><div class="header"><div class="banner-container"><div class="banner-shape"><div id="banner-title" class="banner-text">{html.escape(sections[0][0])}</div></div><div id="banner-subtitle" class="banner-subtitle">{html.escape(sections[0][1])}</div></div></div><div class="slides-area">{slides}</div>{nav(len(sections))}</div><script>const slides=document.querySelectorAll('.slide'),bar=document.getElementById('bar'),counter=document.getElementById('counter'),btnPrev=document.getElementById('btnPrev'),btnNext=document.getElementById('btnNext');let currentSlide=0;function showSlide(index){{if(index<0)index=0;if(index>=slides.length)index=slides.length-1;slides.forEach(s=>s.classList.remove('active'));currentSlide=index;slides[currentSlide].classList.add('active');const c=slides[currentSlide].querySelector('.content-card');if(c)c.scrollTo(0,0);btnPrev.disabled=currentSlide===0;btnNext.disabled=currentSlide===slides.length-1;counter.innerText=currentSlide+1;bar.style.width=((currentSlide+1)/slides.length*100)+'%';document.getElementById('banner-title').innerText=slides[currentSlide].dataset.title;document.getElementById('banner-subtitle').innerText=slides[currentSlide].dataset.subtitle}}btnNext.onclick=()=>showSlide(currentSlide+1);btnPrev.onclick=()=>showSlide(currentSlide-1);document.addEventListener('keydown',e=>{{if(e.key==='ArrowRight'||e.key===' ')showSlide(currentSlide+1);if(e.key==='ArrowLeft')showSlide(currentSlide-1)}});showSlide(0);</script></body></html>'''

