for key,(meta,sections) in content.items():
    meta=dict(meta,id=key,type='slide',level='SD',totalSlides=len(sections),slideUrl=f'./slides/{key}.html',embedUrl=f'slides/{key}.html',prerequisiteStepIds=[])
    meta['learningObjectives']=meta.pop('objectives')
    meta['practice']={'type':'guided_reading','description':'Menyelesaikan pembacaan, observasi visual, dan checkpoint quiz.'}
    meta['completionCriteria']={'quizScoreMin':100,'interactiveCompleted':True,'description':'Menyelesaikan semua slide dan checkpoint quiz.'}
    meta['bookmarks']=[{'slideIndex':i,'label':x[0]} for i,x in enumerate(sections)]
    meta['quizzes']=[{'question':'Checkpoint tersedia di dalam slide interaktif.','options':['Baca ulang slide','Lanjut tanpa mencoba','Tutup materi'],'answer':0,'explanation':'Baca ulang bagian yang belum jelas lalu coba lagi.','embedded':True}]
    (SLIDES/f'{key}.html').write_text(html_doc(meta,sections),encoding='utf-8')
    (SLIDES/f'{key}.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2),encoding='utf-8')
    (DRAFT/f'{key}.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2),encoding='utf-8')
print('Rebuilt',len(content),'Scratch SD bridges with existing bridge design and real Scratch visuals.')
